const manifest = $input.first().json;
const slackBlocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "⚠️ Supply Chain Feasibility Gate: Approval Required"
    }
  },
  {
    "type": "section",
    "fields": [
      { "type": "mrkdwn", "text": `*Store:* ${manifest.target_store}` },
      { "type": "mrkdwn", "text": `*SKU:* ${manifest.sku_id}` },
      { "type": "mrkdwn", "text": `*Units:* ${manifest.units_transferred}` },
      { "type": "mrkdwn", "text": `*Freight Cost:* $${manifest.estimated_freight_cost}` }
    ]
  }
];
return [{ json: { blocks: slackBlocks, manifest } }];
